select SUM(stock.amount) AS ItemAmt, GROUP_CONCAT(DISTINCT stock.vno ORDER BY stock.vno ASC) AS vno_group, itemcatmas.RevCode, stock.restcode, stock.vdate, itemcatmast.AcCode, MAX(depart.short_name) AS DShortName from `stock` left join `itemmast` on `stock`.`item` = `itemmast`.`Code` and `stock`.`itemrestcode` = `itemmast`.`RestCode` and `itemmast`.`Property_ID` = 133 left join `itemcatmast` on `itemmast`.`ItemCatCode` = `itemcatmast`.`Code` and `itemcatmast`.`RestCode` = `itemmast`.`RestCode` and `itemcatmast`.`propertyid` = 133 left join `depart` on `stock`.`restcode` = `depart`.`dcode` and `depart`.`propertyid` = 133 where date(`stock`.`vdate`) = 2026-04-01 and `stock`.`propertyid` = 133 and `stock`.`delflag` \u003C\u003E Y and stock.vtype = CONCAT('B', COALESCE(depart.short_name, '')) and `depart`.`rest_type` in (Outlet, Room Service) group by stock.restcode, stock.vdate, itemcatmast.RevCode, itemcatmast.AcCode